const sitemapGroups = [
  {file:'sitemap-main.xml', paths:['/', '/blog/', '/blog/fire-wise-plot-clearing-hermanus/', '/blog/palm-tree-trimming-removal-costs/', '/blog/tree-removal-permission-hermanus/', '/blog/tree-felling-prices-hermanus/', '/blog/neighbours-tree-overhanging-property/', '/blog/stump-grinding-vs-stump-removal/', '/blog/prepare-property-for-tree-felling/', '/blog/best-time-to-trim-trees-western-cape/', '/blog/signs-a-tree-is-dangerous/', '/blog/prevent-regrowth-after-plot-clearing/'], changefreq:'yearly', priority:'0.8'},
  {file:'sitemap-services.xml', paths:['/services/', ...services.map(service=>`/services/${service.slug}/`)], changefreq:'monthly', priority:'0.9'},
  {file:'sitemap-areas.xml', paths:['/areas/', ...areas.map(area=>`/areas/${area.slug}/`)], changefreq:'monthly', priority:'0.7'},
  {file:'sitemap-service-areas.xml', paths:areas.flatMap(area=>services.map(service=>`/areas/${area.slug}/${service.slug}/`)), changefreq:'monthly', priority:'0.7'}
];
function writeSitemap({file,paths,changefreq,priority}) {
  const entries = paths.map(url=>`  <url><loc>${BASE}${url}</loc><lastmod>${DATE}</lastmod><changefreq>${url==='/'?'monthly':changefreq}</changefreq><priority>${url==='/'?'1.0':priority}</priority></url>`).join('\n');
  fs.writeFileSync(path.join(root,file),`<?xml version="1.0" encoding="UTF-8"?>\n<urlset xmlns="http://www.sitemaps.org/schemas/sitemap/0.9">\n${entries}\n</urlset>\n`);
}
sitemapGroups.forEach(writeSitemap);
const sitemapIndex = `<?xml version="1.0" encoding="UTF-8"?>\n<sitemapindex xmlns="http://www.sitemaps.org/schemas/sitemap/0.9">\n${sitemapGroups.map(({file})=>`  <sitemap><loc>${BASE}/${file}</loc><lastmod>${DATE}</lastmod></sitemap>`).join('\n')}\n</sitemapindex>\n`;
fs.writeFileSync(path.join(root,'sitemap_index.xml'),sitemapIndex);
fs.writeFileSync(path.join(root,'sitemap.xml'),sitemapIndex);
console.log(`Generated ${services.length} core service pages, ${areas.length} area hubs, ${areas.length*services.length} local service pages, and 2 directory pages.`);
console.log(`Sitemap index references ${sitemapGroups.length} sitemaps containing ${sitemapGroups.reduce((total,group)=>total+group.paths.length,0)} URLs.`);
